import { useEffect, useState } from "react";
import { db, auth } from "../../firebase";  // Adjust the import path
import { doc, getDoc, collection, query, where, getDocs, updateDoc } from "firebase/firestore";
import { Card, CardBody, CardTitle, Container, Row, Col } from "reactstrap";

const Header = () => {
  const [stats, setStats] = useState({
    carbonFootprint: 0,
    carbonCredits: 0,
    reductionProgress: 0,
    rank: "Bronze",
  });

  useEffect(() => {
    const fetchUserStats = async () => {
      if (!auth.currentUser) return;

      const userRef = doc(db, "users", auth.currentUser.uid);
      const userSnap = await getDoc(userRef);

      let userData = userSnap.exists() ? userSnap.data() : {};
      let carbonCredits = userData.carbonCredits || 0;
      let rank = userData.rank || "Bronze";

      // Fetch carbon logs
      const logsRef = collection(db, "carbon_logs");
      const logsQuery = query(logsRef, where("userId", "==", auth.currentUser.uid));
      const logsSnap = await getDocs(logsQuery);

      let totalEmissions = 0;
      let logCount = 0;
      let previousMonthEmissions = 0;

      logsSnap.forEach((doc) => {
        const log = doc.data();
        totalEmissions += log.carbonEmission || 0;
        logCount++;

        if (log.date && new Date(log.date) < new Date(new Date().setMonth(new Date().getMonth() - 1))) {
          previousMonthEmissions += log.carbonEmission || 0;
        }
      });

      const averageEmissions = logCount > 0 ? totalEmissions / logCount : 0;

      // Calculate reduction progress
      let reductionProgress = previousMonthEmissions > 0
        ? ((previousMonthEmissions - totalEmissions) / previousMonthEmissions) * 100
        : 0;

      setStats({
        carbonFootprint: averageEmissions.toFixed(2),
        carbonCredits,
        reductionProgress: reductionProgress.toFixed(2),
        rank,
      });
    };

    fetchUserStats();
  }, []);

  return (
    <>
      <div className="header bg-gradient-info pb-8 pt-5 pt-md-8">
        <Container fluid>
          <div className="header-body">
            <Row>
              <Col lg="6" xl="3">
                <Card className="card-stats mb-4 mb-xl-0">
                  <CardBody>
                    <Row>
                      <div className="col">
                        <CardTitle tag="h5" className="text-uppercase text-muted mb-0">
                          Carbon Footprint (kg CO₂)
                        </CardTitle>
                        <span className="h2 font-weight-bold mb-0">
                          {stats.carbonFootprint} kg
                        </span>
                      </div>
                    </Row>
                  </CardBody>
                </Card>
              </Col>

              <Col lg="6" xl="3">
                <Card className="card-stats mb-4 mb-xl-0">
                  <CardBody>
                    <Row>
                      <div className="col">
                        <CardTitle tag="h5" className="text-uppercase text-muted mb-0">
                          Carbon Credits Earned
                        </CardTitle>
                        <span className="h2 font-weight-bold mb-0">
                          {stats.carbonCredits}
                        </span>
                      </div>
                    </Row>
                  </CardBody>
                </Card>
              </Col>

              <Col lg="6" xl="3">
                <Card className="card-stats mb-4 mb-xl-0">
                  <CardBody>
                    <Row>
                      <div className="col">
                        <CardTitle tag="h5" className="text-uppercase text-muted mb-0">
                          Carbon Reduction Progress (%)
                        </CardTitle>
                        <span className="h2 font-weight-bold mb-0">
                          {stats.reductionProgress}%
                        </span>
                      </div>
                    </Row>
                  </CardBody>
                </Card>
              </Col>

              <Col lg="6" xl="3">
                <Card className="card-stats mb-4 mb-xl-0">
                  <CardBody>
                    <Row>
                      <div className="col">
                        <CardTitle tag="h5" className="text-uppercase text-muted mb-0">
                          Rank
                        </CardTitle>
                        <span className="h2 font-weight-bold mb-0">
                          {stats.rank}
                        </span>
                      </div>
                    </Row>
                  </CardBody>
                </Card>
              </Col>
            </Row>
          </div>
        </Container>
      </div>
    </>
  );
};

export default Header;
